namespace CytoLex.Core.Tests.Batch;

/// <summary>The batch sample files of <c>tests/data/batch/</c> (generated by <c>kb samples</c>), copied to the test output.</summary>
internal static class BatchSamples
{
    public static string Dir(string edition = "2016") => Path.Combine(AppContext.BaseDirectory, "data", "batch", edition);

    public static string PathOf(string file, string edition = "2016") => Path.Combine(Dir(edition), file);
}
